*{box-sizing:border-box} :root{color-scheme:dark;--bg:#10131c;--panel:#191d27;--line:#2b303c;--muted:#858d9e;--text:#f4f3ef;--lime:#d8f36a;--orange:#ffab70}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:'Space Grotesk',sans-serif}body{padding:0 24px;background:radial-gradient(ellipse at 60% -30%,#272c3c 0,transparent 58%),#10131c}.game-shell{max-width:1450px;margin:0 auto}.topbar{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #2a2e3a}.brand{display:flex;align-items:center;gap:11px;color:#f6f4ee;text-decoration:none;font-size:15px;font-weight:700;letter-spacing:.09em}.brand-mark{display:grid;place-items:center;width:31px;height:31px;border:1px solid #646d4f;border-radius:50%;color:var(--lime);font-size:20px}.brand-light{color:var(--lime)}.mission-tag,.panel-kicker,.stat-label,.stat-foot,.controls-strip,.run-footer,.page-footer{font-family:'DM Mono',monospace;letter-spacing:.09em}.mission-tag{font-size:10px;color:#a6acb8}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px #d8f36688;margin-right:8px}.tag-divider{color:#555c68;margin:0 8px}.icon-button{width:35px;height:35px;border:1px solid #353a46;border-radius:9px;background:#1a1e29;color:#d4d7de;font-size:17px;cursor:pointer}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 315px;gap:18px;padding:20px 0 18px}.game-column{min-width:0}.canvas-wrap{position:relative;width:100%;aspect-ratio:1000/650;border:1px solid #303541;border-radius:12px;overflow:hidden;background:#171b26;box-shadow:0 24px 70px #0005}canvas{width:100%;height:100%;display:block;image-rendering:auto}.screen-overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#090b10bb,#111522a6);backdrop-filter:blur(4px);transition:opacity .2s}.screen-overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(500px,85%);padding:30px 34px;border:1px solid #4a505b;border-radius:14px;background:#171b25ed;box-shadow:0 20px 80px #0009}.eyebrow{font-family:'DM Mono',monospace;font-size:10px;color:var(--lime);letter-spacing:.18em}.overlay-card h2{font-size:36px;line-height:1.04;margin:12px 0 12px;letter-spacing:-.05em}.overlay-card p{color:#aab1bf;line-height:1.6;font-size:14px}.overlay-card .fine{font:10px 'DM Mono',monospace;color:#828a98;letter-spacing:.1em;margin-top:16px}.primary-button{display:flex;align-items:center;justify-content:center;gap:12px;width:100%;height:48px;margin-top:21px;border:0;border-radius:8px;background:var(--lime);color:#171b1c;font:700 12px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer;transition:transform .15s,filter .15s}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.05)}.shop-list{display:grid;gap:9px;margin:20px 0 8px}.upgrade-option{display:grid;grid-template-columns:1fr auto;align-items:center;gap:4px;padding:13px;border:1px solid #363d49;border-radius:8px;background:#1c212c}.upgrade-option b{font-size:14px}.upgrade-option small{grid-column:1;color:#959eac;font-size:11px}.upgrade-option button{grid-column:2;grid-row:1/3;min-width:82px;height:34px;border:1px solid #59604b;border-radius:6px;background:#d8f36a;color:#20251a;font:700 11px 'DM Mono',monospace;cursor:pointer}.upgrade-option button:disabled{background:#343944;color:#848b97;border-color:#343944;cursor:default}.toast{position:absolute;left:50%;top:19px;transform:translate(-50%,-12px);padding:10px 16px;border:1px solid #748148;border-radius:7px;background:#20291cd9;color:var(--lime);font:11px 'DM Mono',monospace;letter-spacing:.04em;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.controls-strip{display:flex;align-items:center;gap:19px;height:43px;padding:0 4px;color:#969ead;font-size:9px}.controls-strip span{display:flex;align-items:center;gap:4px;white-space:nowrap}.controls-strip kbd{display:inline-grid;place-items:center;height:19px;min-width:19px;padding:0 4px;border:1px solid #434957;border-radius:4px;background:#1c202b;color:#dde0e5;font:9px 'DM Mono',monospace}.controls-strip .controls-note{margin-left:auto;color:#6d7585;font-size:8px}.dashboard{display:flex;flex-direction:column;gap:11px}.panel{border:1px solid var(--line);border-radius:10px;background:linear-gradient(145deg,#1a1e28,#171a23)}.mission-panel{padding:19px 18px 16px}.panel-kicker{font-size:9px;color:#9aa2b2}.contract-id{float:right;color:#737b8a}.mission-panel h1{margin:14px 0 9px;font-size:31px;letter-spacing:-.055em;line-height:1.02}.mission-panel p{margin:0;color:#9ca4b2;font-size:12px;line-height:1.55}.objective-row{display:flex;align-items:center;gap:7px;margin:19px 0 9px;font:9px 'DM Mono',monospace;letter-spacing:.05em;color:#bdc3cc}.objective-icon{color:var(--lime);font-size:14px}.objective-row b{color:#fff}.objective-count{margin-left:auto;color:var(--lime)}.progress-track{height:5px;border-radius:4px;background:#303541;overflow:hidden}.progress-track i{display:block;width:0;height:100%;border-radius:4px;background:var(--lime);transition:width .3s}.stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.stat-card{padding:13px 14px 12px}.stat-label{display:block;color:#9aa2b1;font-size:9px}.stat-card strong{display:block;margin:7px 0 4px;font-size:27px;line-height:1;color:#f6f5f0}.stat-card strong small{font-size:14px;color:#88909e}.stat-foot{font-size:8px;color:#717989}.status-panel{padding:14px 15px 12px}.status-head{display:flex;justify-content:space-between;margin-bottom:12px}.status-live{color:var(--lime);font:8px 'DM Mono',monospace;letter-spacing:.07em}.status-line{display:flex;align-items:center;justify-content:space-between;padding:7px 0;border-top:1px solid #292e39;color:#9ca4b2;font-size:11px}.status-line b{color:#e1e2e4;font:10px 'DM Mono',monospace}.health-dots{display:flex;gap:4px}.health-dots i{width:10px;height:6px;border-radius:2px;background:var(--lime)}.health-dots i.off{background:#3a404b}.mini-meter{width:81px;height:5px;border-radius:4px;background:#303541;overflow:hidden}.mini-meter i{display:block;width:100%;height:100%;background:#79d7c6;transition:width .1s}.shop-button{display:flex;align-items:center;gap:11px;text-align:left;width:100%;padding:11px 13px;border:1px solid #596244;border-radius:9px;background:linear-gradient(110deg,#252c21,#1b211e);color:#eff1e5;cursor:pointer;transition:.15s}.shop-button:hover{border-color:var(--lime);transform:translateY(-1px)}.shop-icon{display:grid;place-items:center;width:31px;height:31px;border-radius:7px;background:#d8f36a;color:#171c1a;font-size:23px}.shop-button b,.shop-button small{display:block}.shop-button b{font:10px 'DM Mono',monospace;letter-spacing:.07em}.shop-button small{margin-top:4px;color:#a0a999;font-size:10px}.button-arrow{margin-left:auto;color:var(--lime);font-size:17px}.tip-panel{display:flex;gap:11px;padding:11px 12px;background:#1a2024;border-color:#303b38}.tip-icon{font-size:20px;color:#83cbbb}.tip-panel p{margin:0;color:#a6afb3;font-size:10px;line-height:1.5}.tip-panel b{font:9px 'DM Mono',monospace;color:#d5d9d4;letter-spacing:.08em}.tip-panel p span{color:var(--lime)}.run-footer{display:flex;justify-content:space-between;padding:5px 2px;color:#727b89;font-size:8px}.run-footer b{margin-left:5px;color:#b9bec8;font-weight:400}.page-footer{display:flex;justify-content:space-between;padding:12px 2px 18px;border-top:1px solid #272b36;color:#697180;font-size:8px}.page-footer i{font-style:normal;color:var(--lime)}.mobile-controls{display:none}
@media(max-width:1050px){body{padding:0 15px}.game-layout{grid-template-columns:minmax(0,1fr) 280px;gap:13px}.mission-panel h1{font-size:27px}.controls-strip{gap:11px}.controls-strip .controls-note{display:none}}
@media(max-width:780px){body{padding:0 10px}.topbar{height:58px}.mission-tag{font-size:8px}.brand{font-size:12px}.game-layout{grid-template-columns:1fr;padding-top:12px}.dashboard{display:grid;grid-template-columns:1fr 1fr;gap:9px}.mission-panel{grid-row:span 2}.stats-grid{gap:8px}.status-panel{grid-column:1/-1}.shop-button{min-height:58px}.tip-panel{grid-column:1/-1}.run-footer{grid-column:1/-1}.controls-strip{height:auto;min-height:38px;flex-wrap:wrap;gap:8px 13px;padding:8px 2px}.page-footer{font-size:7px}.mobile-controls{display:flex;position:absolute;inset:auto 0 13px;justify-content:space-between;align-items:end;padding:0 14px;pointer-events:none}.dpad{display:grid;grid-template:repeat(2,38px)/repeat(3,38px);gap:3px;pointer-events:auto}.dpad button,.touch-actions button{border:1px solid #ffffff44;background:#141a20bb;color:white;backdrop-filter:blur(5px);border-radius:8px;font-size:14px;touch-action:none}.dpad button:nth-child(1){grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.touch-actions{display:flex;gap:7px;pointer-events:auto}.touch-actions button{height:40px;padding:0 12px;color:var(--lime);font:9px 'DM Mono',monospace;letter-spacing:.05em}.screen-overlay{backdrop-filter:blur(3px)}}
@media(max-width:480px){.mission-tag{display:none}.canvas-wrap{aspect-ratio:4/3}.dashboard{grid-template-columns:1fr 1fr}.mission-panel{grid-column:1/-1;grid-row:auto;padding:13px}.mission-panel h1 br{display:none}.mission-panel h1{font-size:23px;margin:8px 0}.mission-panel p{font-size:11px}.objective-row{margin:11px 0 7px}.stats-grid{grid-column:1/-1}.status-panel{padding:11px}.tip-panel{padding:9px}.run-footer{font-size:7px}.controls-strip{font-size:8px;gap:7px}.controls-strip span:nth-child(2){display:none}.overlay-card{padding:23px 20px}.overlay-card h2{font-size:30px}.page-footer span:nth-child(2){display:none}}

(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const $ = (selector) => document.querySelector(selector);
  const overlay = $('#screen-overlay'), overlayCard = $('#overlay-card'), toastEl = $('#toast');
  const held = new Set();
  let state = 'title', last = performance.now(), elapsed = 0, toastTimer = 0;
  let soundOn = false, audioCtx = null, pulseCooldown = 0, damageCooldown = 0;
  let credits = 0, delivered = 0, collected = 0, capacity = 10, health = 3;
  let upgrades = { rover: false, cargo: false, pulse: false };
  let player = { x: 228, y: 330, angle: 0, speed: 180, cargo: 0, stun: 0 };
  let crawler = { x: 795, y: 255, speed: 66, stun: 0, phase: 0 };
  let scraps = [], particles = [], rocks = [], dust = [], stars = [];
  let highScore = Number(localStorage.getItem('lunarRecyclerBest') || 0);
  $('#best-run').textContent = String(highScore);

  function rand(min, max) { return min + Math.random() * (max - min); }
  function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }
  function nearBase() { return Math.hypot(player.x - 125, player.y - 325) < 112; }
  function initWorld() {
    rocks = []; dust = []; stars = []; scraps = [];
    for (let i = 0; i < 80; i++) stars.push({ x: rand(0,W), y: rand(0,H), r: rand(.4,1.4), a: rand(.15,.55) });
    for (let i = 0; i < 52; i++) {
      let x, y;
      do { x = rand(15,W-15); y = rand(28,H-20); } while (Math.hypot(x-125,y-325)<120);
      rocks.push({x,y,r:rand(3,14),rot:rand(0,6.28),shade:Math.floor(rand(35,68))});
    }
    for (let i = 0; i < 140; i++) dust.push({x:rand(0,W),y:rand(0,H),r:rand(.5,2.4),a:rand(.035,.13)});
    for (let i = 0; i < 18; i++) spawnScrap();
  }
  function spawnScrap() {
    let x,y,tries=0;
    do { x=rand(185,W-30); y=rand(60,H-35); tries++; }
    while (tries<100 && (Math.hypot(x-125,y-325)<145 || rocks.some(r=>Math.hypot(x-r.x,y-r.y)<r.r+26)));
    scraps.push({x,y,spin:rand(0,6.28),value:rand(.7,1.3)});
  }
  function setOverlay(html, show=true) { overlayCard.innerHTML=html; overlay.classList.toggle('hidden',!show); }
  function hideOverlay() { overlay.classList.add('hidden'); }
  function showToast(message) {
    toastEl.textContent=message; toastEl.classList.add('show'); toastTimer=1.8;
  }
  function beep(frequency=440, duration=.07, type='sine') {
    if (!soundOn) return;
    try { audioCtx ||= new (window.AudioContext||window.webkitAudioContext)(); const o=audioCtx.createOscillator(),g=audioCtx.createGain(); o.type=type;o.frequency.value=frequency;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration); } catch (_) {}
  }
  function startGame() {
    state='playing'; elapsed=0; credits=0; delivered=0; collected=0; capacity=10; health=3;
    upgrades={rover:false,cargo:false,pulse:false};player={x:228,y:330,angle:0,speed:180,cargo:0,stun:0};
    crawler={x:795,y:255,speed:66,stun:0,phase:0};pulseCooldown=0;damageCooldown=0;particles=[];initWorld();
    hideOverlay(); updateUI();
  }
  function openTitle() {
    state='title';
    setOverlay(`<div class="eyebrow">LUNAR RECYCLING CORP. &nbsp;·&nbsp; NEW CONTRACT</div><h2>One small step<br>for clean-up.</h2><p>The old landing zone is buried in scrap. Salvage everything you can, dodge the crater crawler, and bring your haul back to base.</p><button class="primary-button" data-start>BEGIN SALVAGE RUN <span>↗</span></button><div class="fine">WASD / ARROWS TO MOVE &nbsp;·&nbsp; SPACE TO PULSE &nbsp;·&nbsp; E AT BASE FOR SHOP</div>`);
  }
  function openShop() {
    if(state!=='playing')return;
    state='shop';
    renderShop();
  }
  const catalog=[
    {id:'rover',name:'Rover treads',description:'Increase movement speed by 30%.',price:100},
    {id:'cargo',name:'Expanded cargo',description:'Add 20 slots to your salvage bay.',price:200},
    {id:'pulse',name:'Pulse amplifier',description:'Double pulse radius and range.',price:150}
  ];
  function renderShop() {
    const items=catalog.map(item=>{const owned=upgrades[item.id], can=credits>=item.price;return `<div class="upgrade-option"><b>${item.name}${owned?' ✓':''}</b><small>${owned?'Installed and ready.':item.description}</small><button data-buy="${item.id}" ${owned||!can?'disabled':''}>${owned?'OWNED':`${item.price} CR`}</button></div>`;}).join('');
    setOverlay(`<div class="eyebrow">CRATER BASE &nbsp;·&nbsp; SERVICE BAY</div><h2>Field upgrades</h2><p>Credits: <b style="color:#d8f36a">${credits} CR</b> &nbsp;·&nbsp; Docked cargo: ${player.cargo} scrap</p><div class="shop-list">${items}</div><button class="primary-button" data-close-shop>BACK TO THE CRATER <span>↗</span></button>`);
  }
  function closeShop() {state='playing';hideOverlay();}
  function purchase(id) {
    const item=catalog.find(i=>i.id===id);
    if(!item||upgrades[id]||credits<item.price)return;
    credits-=item.price;upgrades[id]=true;
    if(id==='rover')player.speed=234;
    if(id==='cargo')capacity+=20;
    if(id==='pulse'){};
    beep(700,.12,'triangle');renderShop();updateUI();
  }
  function interact() {
    if(state==='shop'){closeShop();return;}
    if(state!=='playing')return;
    if(nearBase())openShop(); else showToast('RETURN TO THE RECYCLER TO DOCK & SHOP');
  }
  function pulse() {
    if(state!=='playing'||pulseCooldown>0)return;
    pulseCooldown=upgrades.pulse?3.5:6;
    const radius=upgrades.pulse?210:145;
    particles.push({x:player.x,y:player.y,r:12,max:radius,life:.45,color:'#9df6e3'});
    if(Math.hypot(player.x-crawler.x,player.y-crawler.y)<radius){crawler.stun=upgrades.pulse?4.8:3.1;showToast('CRAWLER DISABLED · MOVE!');beep(170,.2,'sawtooth');}
    else beep(300,.09,'triangle');
  }
  function movePlayer(dt) {
    if(player.stun>0){player.stun-=dt;return;}
    const up=held.has('w')||held.has('arrowup'),down=held.has('s')||held.has('arrowdown');
    const left=held.has('a')||held.has('arrowleft'),right=held.has('d')||held.has('arrowright');
    let dx=(right?1:0)-(left?1:0),dy=(down?1:0)-(up?1:0);
    if(dx||dy){const m=Math.hypot(dx,dy);dx/=m;dy/=m;player.angle=Math.atan2(dy,dx);player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt;}
    player.x=Math.max(22,Math.min(W-22,player.x));player.y=Math.max(45,Math.min(H-25,player.y));
  }
  function updateGame(dt) {
    elapsed+=dt;pulseCooldown=Math.max(0,pulseCooldown-dt);damageCooldown=Math.max(0,damageCooldown-dt);
    movePlayer(dt);
    if(crawler.stun>0)crawler.stun-=dt;
    else {const dx=player.x-crawler.x,dy=player.y-crawler.y,d=Math.hypot(dx,dy)||1;const speed=crawler.speed+(upgrades.rover?5:0);crawler.x+=dx/d*speed*dt;crawler.y+=dy/d*speed*dt;crawler.phase+=dt*4;}
    for(const s of scraps){s.spin+=dt*1.6;if(Math.hypot(player.x-s.x,player.y-s.y)<25&&player.cargo<capacity){player.cargo++;collected++;particles.push({x:s.x,y:s.y,r:3,max:30,life:.3,color:'#d8f36a'});scraps.splice(scraps.indexOf(s),1);spawnScrap();beep(560,.04,'sine');if(player.cargo===capacity)showToast('CARGO FULL · RETURN TO BASE');break;}}
    if(nearBase()&&player.cargo>0){const sold=player.cargo;credits+=sold*12;delivered+=sold;player.cargo=0;showToast(`SALVAGE DOCKED · +${sold*12} CREDITS`);beep(820,.13,'triangle');if(delivered>=30){state='won';highScore=Math.max(highScore,delivered);localStorage.setItem('lunarRecyclerBest',String(highScore));openEnd(true);}}
    if(damageCooldown<=0&&Math.hypot(player.x-crawler.x,player.y-crawler.y)<39){damageCooldown=1.5;health--;player.cargo=Math.max(0,player.cargo-3);player.stun=.38;const d=Math.hypot(player.x-crawler.x,player.y-crawler.y)||1;player.x=Math.max(24,Math.min(W-24,player.x+(player.x-crawler.x)/d*48));player.y=Math.max(45,Math.min(H-24,player.y+(player.y-crawler.y)/d*48));particles.push({x:player.x,y:player.y,r:5,max:55,life:.4,color:'#ff8a75'});beep(120,.18,'square');showToast(`HIT! LOST ${Math.min(3,player.cargo+3)} SCRAP · ${health} INTEGRITY`);if(health<=0){state='lost';openEnd(false);}}
    for(const p of particles){p.r+=(p.max-p.r)*.18;p.life-=dt;}particles=particles.filter(p=>p.life>0);
    if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show');}
    updateUI();
  }
  function openEnd(won) {
    setOverlay(`<div class="eyebrow">${won?'CONTRACT COMPLETE':'ROVER DISABLED'} &nbsp;·&nbsp; ${won?'NICE WORK':'RUN ENDED'}</div><h2>${won?'Crater cleared.':'Lost in the dust.'}</h2><p>${won?'You recovered and delivered 30 pieces of lunar salvage. The colony owes you one.':'The crawler got the better of your rover this time. Reset and try another route.'}<br><br><b style="color:#d8f36a">${delivered} SCRAP DELIVERED</b> &nbsp;·&nbsp; ${credits} CREDITS REMAIN</p><button class="primary-button" data-start>RUN IT BACK <span>↗</span></button><div class="fine">YOUR BEST RUN: ${Math.max(highScore,delivered)} SCRAP</div>`);
  }
  function updateUI() {
    $('#credits').textContent=credits;$('#cargo').textContent=player.cargo;$('#capacity').textContent=`/ ${capacity}`;
    $('#goal-count').textContent=`${Math.min(delivered,30)} / 30`;$('#goal-progress').style.width=`${Math.min(100,delivered/30*100)}%`;
    $('#drive-status').textContent=upgrades.rover?'Rover treads':'Standard';
    $('#health-dots').innerHTML=Array.from({length:3},(_,i)=>`<i class="${i>=health?'off':''}"></i>`).join('');
    $('#pulse-meter').style.width=`${Math.max(0,100-pulseCooldown/(upgrades.pulse?3.5:6)*100)}%`;
    const m=Math.floor(elapsed/60),s=Math.floor(elapsed%60);$('#run-time').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
    $('#best-run').textContent=String(Math.max(highScore,delivered));
  }

  function polygon(points,fill,stroke=null,width=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
  function drawBackground(now) {
    const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#262b36');g.addColorStop(.52,'#20242e');g.addColorStop(1,'#181c26');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    ctx.save();ctx.globalAlpha=.48;const glow=ctx.createRadialGradient(690,250,10,690,250,470);glow.addColorStop(0,'#39404a');glow.addColorStop(1,'#24283200');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);ctx.restore();
    for(const s of stars){ctx.globalAlpha=s.a*(.78+.22*Math.sin(now*.001+s.x));ctx.fillStyle='#d9e3e5';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    for(const d of dust){ctx.globalAlpha=d.a;ctx.fillStyle='#d3c8ad';ctx.beginPath();ctx.arc(d.x,d.y,d.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    // Long, faint survey lanes and contour rings.
    ctx.save();ctx.setLineDash([3,12]);ctx.strokeStyle='#a7ac9a';ctx.globalAlpha=.09;ctx.lineWidth=1;
    for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(590,310,100+i*76,45+i*39,-.12,0,Math.PI*2);ctx.stroke();}ctx.restore();
    // The safe radius makes the return-to-base loop legible.
