(() => {
  'use strict';
  const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height;
  const $=s=>document.querySelector(s),overlay=$('#screen-overlay'),overlayCard=$('#overlay-card'),toastEl=$('#toast');
  const held=new Set();let state='title',last=performance.now(),elapsed=0,toastTimer=0,soundOn=false,audioCtx=null,pulseCooldown=0,damageCooldown=0;
  let credits=0,delivered=0,collected=0,capacity=10,health=3;
