  let scraps=[],particles=[],rocks=[],dust=[],stars=[];
  let highScore=Number(localStorage.getItem('lunarRecyclerBest')||0);$('#best-run').textContent=String(highScore);
  function rand(a,b){return a+Math.random()*(b-a)}
  function nearBase(){return Math.hypot(player.x-125,player.y-325)<112}
  function initWorld(){rocks=[];dust=[];stars=[];scraps=[];
    for(let i=0;i<80;i++)stars.push({x:rand(0,W),y:rand(0,H),r:rand(.4,1.4),a:rand(.15,.55)});
    for(let i=0;i<52;i++){let x,y;do{x=rand(15,W-15);y=rand(28,H-20)}while(Math.hypot(x-125,y-325)<120);rocks.push({x,y,r:rand(3,14),rot:rand(0,6.28),shade:Math.floor(rand(35,68))})}
