  function spawnScrap(){let x,y,tries=0;do{x=rand(185,W-30);y=rand(60,H-35);tries++}while(tries<100&&(Math.hypot(x-125,y-325)<145||rocks.some(r=>Math.hypot(x-r.x,y-r.y)<r.r+26)));scraps.push({x,y,spin:rand(0,6.28)})}
  function setOverlay(html,show=true){overlayCard.innerHTML=html;overlay.classList.toggle('hidden',!show)}
  function hideOverlay(){overlay.classList.add('hidden')}
  function showToast(message){toastEl.textContent=message;toastEl.classList.add('show');toastTimer=1.8}
  function beep(f=440,d=.07,type='sine'){if(!soundOn)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch(_){}}
  function startGame(){state='playing';elapsed=0;credits=0;delivered=0;collected=0;capacity=10;health=3;upgrades={rover:false,cargo:false,pulse:false};player={x:228,y:330,angle:0,speed:180,cargo:0,stun:0};crawler={x:795,y:255,speed:66,stun:0,phase:0};pulseCooldown=0;damageCooldown=0;particles=[];initWorld();hideOverlay();updateUI()}
  function openTitle(){state='title';setOverlay(`<div class="eyebrow">LUNAR RECYCLING CORP. &nbsp;·&nbsp; NEW CONTRACT</div><h2>One small step<br>for clean-up.</h2><p>The old landing zone is buried in scrap. Salvage everything you can, dodge the crater crawler, and bring your haul back to base.</p><button class="primary-button" data-start>BEGIN SALVAGE RUN <span>↗</span></button><div class="fine">WASD / ARROWS TO MOVE &nbsp;·&nbsp; SPACE TO PULSE &nbsp;·&nbsp; E AT BASE FOR SHOP</div>`)}
  const catalog=[{id:'rover',name:'Rover treads',description:'Increase movement speed by 30%.',price:100},{id:'cargo',name:'Expanded cargo',description:'Add 20 slots to your salvage bay.',price:200},{id:'pulse',name:'Pulse amplifier',description:'Double pulse radius and range.',price:150}];
  function renderShop(){const items=catalog.map(i=>{const owned=upgrades[i.id],can=credits>=i.price;return `<div class="upgrade-option"><b>${i.name}${owned?' ✓':''}</b><small>${owned?'Installed and ready.':i.description}</small><button data-buy="${i.id}" ${owned||!can?'disabled':''}>${owned?'OWNED':`${i.price} CR`}</button></div>`}).join('');setOverlay(`<div class="eyebrow">CRATER BASE &nbsp;·&nbsp; SERVICE BAY</div><h2>Field upgrades</h2><p>Credits: <b style="color:#d8f36a">${credits} CR</b> &nbsp;·&nbsp; Docked cargo: ${player.cargo} scrap</p><div class="shop-list">${items}</div><button class="primary-button" data-close-shop>BACK TO THE CRATER <span>↗</span></button>`)}
