  function closeShop(){state='playing';hideOverlay()}
  function purchase(id){const item=catalog.find(i=>i.id===id);if(!item||upgrades[id]||credits<item.price)return;credits-=item.price;upgrades[id]=true;if(id==='rover')player.speed=234;if(id==='cargo')capacity+=20;beep(700,.12,'triangle');renderShop();updateUI()}
  function interact(){if(state==='shop'){closeShop();return}if(state!=='playing')return;if(nearBase())openShop();else showToast('RETURN TO THE RECYCLER TO DOCK & SHOP')}
  function pulse(){if(state!=='playing'||pulseCooldown>0)return;pulseCooldown=upgrades.pulse?3.5:6;const radius=upgrades.pulse?210:145;particles.push({x:player.x,y:player.y,r:12,max:radius,life:.45,color:'#9df6e3'});if(Math.hypot(player.x-crawler.x,player.y-crawler.y)<radius){crawler.stun=upgrades.pulse?4.8:3.1;showToast('CRAWLER DISABLED · MOVE!');beep(170,.2,'sawtooth')}else beep(300,.09,'triangle')}
  function movePlayer(dt){if(player.stun>0){player.stun-=dt;return}const up=held.has('w')||held.has('arrowup'),down=held.has('s')||held.has('arrowdown'),left=held.has('a')||held.has('arrowleft'),right=held.has('d')||held.has('arrowright');let dx=(right?1:0)-(left?1:0),dy=(down?1:0)-(up?1:0);if(dx||dy){const m=Math.hypot(dx,dy);dx/=m;dy/=m;player.angle=Math.atan2(dy,dx);player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt}player.x=Math.max(22,Math.min(W-22,player.x));player.y=Math.max(45,Math.min(H-25,player.y))}
  function updateGame(dt){elapsed+=dt;pulseCooldown=Math.max(0,pulseCooldown-dt);damageCooldown=Math.max(0,damageCooldown-dt);movePlayer(dt);
    if(crawler.stun>0)crawler.stun-=dt;else{const dx=player.x-crawler.x,dy=player.y-crawler.y,d=Math.hypot(dx,dy)||1;crawler.x+=dx/d*(crawler.speed+(upgrades.rover?5:0))*dt;crawler.y+=dy/d*(crawler.speed+(upgrades.rover?5:0))*dt;crawler.phase+=dt*4}
    for(const s of scraps){s.spin+=dt*1.6;if(Math.hypot(player.x-s.x,player.y-s.y)<25&&player.cargo<capacity){player.cargo++;collected++;particles.push({x:s.x,y:s.y,r:3,max:30,life:.3,color:'#d8f36a'});scraps.splice(scraps.indexOf(s),1);spawnScrap();beep(560,.04);if(player.cargo===capacity)showToast('CARGO FULL · RETURN TO BASE');break}}
    if(nearBase()&&player.cargo>0){const sold=player.cargo;credits+=sold*12;delivered+=sold;player.cargo=0;showToast(`SALVAGE DOCKED · +${sold*12} CREDITS`);beep(820,.13,'triangle');if(delivered>=30){state='won';highScore=Math.max(highScore,delivered);localStorage.setItem('lunarRecyclerBest',String(highScore));openEnd(true)}}
    if(damageCooldown<=0&&Math.hypot(player.x-crawler.x,player.y-crawler.y)<39){damageCooldown=1.5;health--;const lost=Math.min(3,player.cargo);player.cargo-=lost;player.stun=.38;const d=Math.hypot(player.x-crawler.x,player.y-crawler.y)||1;player.x=Math.max(24,Math.min(W-24,player.x+(player.x-crawler.x)/d*48));player.y=Math.max(45,Math.min(H-24,player.y+(player.y-crawler.y)/d*48));particles.push({x:player.x,y:player.y,r:5,max:55,life:.4,color:'#ff8a75'});beep(120,.18,'square');showToast(`HIT! LOST ${lost} SCRAP · ${health} INTEGRITY`);if(health<=0){state='lost';openEnd(false)}}
    for(const p of particles){p.r+=(p.max-p.r)*.18;p.life-=dt}particles=particles.filter(p=>p.life>0);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}updateUI()}
  function openEnd(won){setOverlay(`<div class="eyebrow">${won?'CONTRACT COMPLETE':'ROVER DISABLED'} &nbsp;·&nbsp; ${won?'NICE WORK':'RUN ENDED'}</div><h2>${won?'Crater cleared.':'Lost in the dust.'}</h2><p>${won?'You recovered and delivered 30 pieces of lunar salvage. The colony owes you one.':'The crawler got the better of your rover this time. Reset and try another route.'}<br><br><b style="color:#d8f36a">${delivered} SCRAP DELIVERED</b> &nbsp;·&nbsp; ${credits} CREDITS REMAIN</p><button class="primary-button" data-start>RUN IT BACK <span>↗</span></button><div class="fine">YOUR BEST RUN: ${Math.max(highScore,delivered)} SCRAP</div>`)}
  function updateUI(){ $('#credits').textContent=credits;$('#cargo').textContent=player.cargo;$('#capacity').textContent=`/ ${capacity}`;$('#goal-count').textContent=`${Math.min(delivered,30)} / 30`;$('#goal-progress').style.width=`${Math.min(100,delivered/30*100)}%`;$('#drive-status').textContent=upgrades.rover?'Rover treads':'Standard';$('#health-dots').innerHTML=Array.from({length:3},(_,i)=>`<i class="${i>=health?'off':''}"></i>`).join('');$('#pulse-meter').style.width=`${Math.max(0,100-pulseCooldown/(upgrades.pulse?3.5:6)*100)}%`;const m=Math.floor(elapsed/60),s=Math.floor(elapsed%60);$('#run-time').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('#best-run').textContent=String(Math.max(highScore,delivered)) }

