input.newString:
  function frame(now){const dt=Math.min(.035,(now-last)/1000||0);last=now;if(state==='playing')updateGame(dt);drawWorld(now);requestAnimationFrame(frame)}
  const keyMap={w:'w',a:'a',s:'s',d:'d',arrowup:'arrowup',arrowleft:'arrowleft',arrowdown:'arrowdown',arrowright:'arrowright'};
  window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(key in keyMap){held.add(keyMap[key]);e.preventDefault()}if(e.repeat)return;if(key===' '||key==='spacebar'){pulse();e.preventDefault()}else if(key==='e'){interact();e.preventDefault()}else if(key==='escape'&&state==='shop')closeShop()});
  window.addEventListener('keyup',e=>held.delete(e.key.toLowerCase()));
  window.addEventListener('blur',()=>held.clear());
  overlay.addEventListener('click',e=>{if(e.target.closest('[data-start]'))startGame();else if(e.target.closest('[data-close-shop]'))closeShop();else{const buy=e.target.closest('[data-buy]');if(buy)purchase(buy.dataset.buy)}});
  $('#shop-button').addEventListener('click',interact);
  $('#sound-button').addEventListener('click',()=>{soundOn=!soundOn;$('#sound-button').classList.toggle('sound-on',soundOn);$('#sound-button').setAttribute('aria-pressed',String(soundOn));if(soundOn){beep(540,.07);if(audioCtx?.state==='suspended')audioCtx.resume()}});
  document.querySelectorAll('[data-dir]').forEach(button=>{const dir=button.dataset.dir;const key={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[dir];const release=()=>held.delete(key);button.addEventListener('pointerdown',e=>{e.preventDefault();held.add(key);button.setPointerCapture(e.pointerId)});button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)});
  document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('pointerdown',e=>{e.preventDefault();if(button.dataset.action==='pulse')pulse();else interact()}));
  initWorld();updateUI();openTitle();requestAnimationFrame(frame);
})();

